#include "Monstey_NavSeamBroadphase.hpp"
#include "Monstey_Core.hpp"
#include <algorithm>
#include <bit>
#include <iostream>
#include <random>
using namespace Monstey;
namespace {
using B=Monstey_NavSeamQuantizedAabb;using P=Monstey_NavSeamHitPair;using J=Monstey_Json;
B Box(unsigned x,unsigned y,unsigned z,unsigned dx,unsigned dy,unsigned dz,unsigned id){return B{{x,y,z,id},{x+dx,y+dy,z+dz,0xdeadbeef}};}
std::vector<P> Reference(std::vector<B>a,std::vector<B>b){struct Entry{unsigned x;bool second;std::size_t ordinal;};std::vector<Entry> order;for(std::size_t i=0;i<a.size();++i)order.push_back({a[i].minimum[0],false,i});for(std::size_t i=0;i<b.size();++i)order.push_back({b[i].minimum[0],true,i});std::stable_sort(order.begin(),order.end(),[](const auto&x,const auto&y){if(x.x!=y.x)return x.x<y.x;return x.second<y.second;});auto sort=[](auto&v){std::stable_sort(v.begin(),v.end(),[](const auto&x,const auto&y){return x.minimum[0]<y.minimum[0];});};sort(a);sort(b);std::vector<P>result;std::size_t ca=0,cb=0;for(const auto&e:order){if(ca==a.size()||cb==b.size())break;const bool side=a[ca].minimum[0]>b[cb].minimum[0];Monstey_Require(e.second==side,"Reference global head order differs");const auto&l=side?b[cb]:a[ca];const auto&others=side?a:b;std::size_t begin=side?ca:cb;for(std::size_t i=begin;i<others.size();++i){const auto&r=others[i];if(r.minimum[0]>=l.maximum[0])break;bool valid=true;for(unsigned axis=1;axis<3;++axis)valid &=std::bit_cast<std::int32_t>(l.maximum[axis]-r.minimum[axis])>=0&&std::bit_cast<std::int32_t>(r.maximum[axis]-l.minimum[axis])>=0;if(valid)result.push_back(side?P{r.minimum[3],l.minimum[3]}:P{l.minimum[3],r.minimum[3]});}if(side)++cb;else++ca;}return result;}
}
int wmain(int argc,wchar_t**argv){try{Monstey_Require(argc==2,"Usage: NEW_REPORT");unsigned groups=0,cases=0;auto Check=[&](std::vector<B>a,std::vector<B>b){const auto originalA=a,originalB=b;const auto expected=Reference(a,b);const auto actual=Monstey_NavSeamBroadphase(a,b);Monstey_Require(expected==actual,"Native sweep pair sequence differs");Monstey_Require(std::equal(a.begin(),a.end(),originalA.begin(),[](const B&x,const B&y){return x.minimum==y.minimum&&x.maximum==y.maximum;}),"First input changed");Monstey_Require(std::equal(b.begin(),b.end(),originalB.begin(),[](const B&x,const B&y){return x.minimum==y.minimum&&x.maximum==y.maximum;}),"Second input changed");++cases;return actual;};Check({},{});Check({Box(1,2,3,4,5,6,123)},{});Check({},{Box(1,2,3,4,5,6,456)});++groups;Monstey_Require(Check({Box(0,0,0,1,1,1,42)},{Box(1,0,0,1,1,1,77)}).empty(),"X touching should be excluded");++groups;Monstey_Require(Check({Box(0,0,0,3,1,1,42)},{Box(1,1,1,3,1,1,77)})==std::vector<P>{{42,77}},"Y/Z touching or hit identity wrong");++groups;Monstey_Require(Check({Box(0,0,0,3,1,1,42)},{Box(1,2,0,3,1,1,77)}).empty(),"Y gap was accepted");++groups;Monstey_Require(Check({Box(0,0,0,3,1,1,42)},{Box(1,0,2,3,1,1,77)}).empty(),"Z gap was accepted");++groups;auto tied=Check({Box(5,0,0,3,1,1,10),Box(5,0,0,3,1,1,11)},{Box(5,0,0,3,1,1,90),Box(5,0,0,3,1,1,91)});Monstey_Require(tied==std::vector<P>{{10,90},{10,91},{11,90},{11,91}},"Equal-X stable/A-first ordering changed");++groups;Check({Box(8,0,0,8,2,2,8),Box(1,0,0,8,2,2,1)},{Box(3,0,0,8,2,2,3),Box(0,0,0,8,2,2,0)});++groups;Check({Box(0x70000000u,0x70000000u,0x70000000u,32,32,32,0xffffffffu)},{Box(0x70000001u,0x70000001u,0x70000001u,32,32,32,0x80000000u)});++groups;Check({Box(0,0,0,0,1,1,2)},{Box(0,0,0,0,1,1,3)});++groups;std::mt19937 random(0x556b18);for(unsigned c=0;c<2048;++c){std::vector<B>a,b;for(unsigned side=0;side<2;++side){auto&v=side?b:a;const unsigned count=random()%40;for(unsigned i=0;i<count;++i)v.push_back(Box(random()%64,random()%64,random()%64,random()%16,random()%16,random()%16,side?i+1000:i+300));}Check(a,b);}++groups;std::vector<B>data;for(unsigned i=0;i<4097;++i)data.push_back(Box(random(),random(),random(),random(),random(),random(),i));const auto sorted=Monstey_NavSeamSortAabbs(data);std::stable_sort(data.begin(),data.end(),[](const B&x,const B&y){return x.minimum[0]<y.minimum[0];});Monstey_Require(std::equal(sorted.begin(),sorted.end(),data.begin(),[](const B&x,const B&y){return x.minimum==y.minimum&&x.maximum==y.maximum;}),"Four-pass unsigned radix sort differs");++groups;Monstey_WriteNewText(argv[1],J::object({{"status","PASS"},{"groups",groups},{"pair_cases",cases},{"randomized_pair_cases",2048},{"unsigned_sort_rows",4097},{"native_program_called",false},{"process_accessed",false},{"scope","Quantized native sort and broadphase pair order only; no nav connection or full seam matcher qualification"}}).dump(2)+"\n");std::cout<<"PASS "<<groups<<" groups, "<<cases<<" ordered pair cases\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}